describe('Sidebar Collapse and Expand Functionality', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should collapse and expand the sidebar on click', () => {
    // Verify sidebar is visible by default
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');
    cy.get('[data-testid="sidebar-menu"]').should('have.class', 'collapsed');

    // Click the sidebar toggle button to collapse
    cy.get('[data-testid="sidebar-toggle"]').click();

    // Verify sidebar is now collapsed
    cy.get('[data-testid="sidebar-menu"]').should('not.have.class', 'collapsed');
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');

    // Click the toggle button again to expand
    cy.get('[data-testid="sidebar-toggle"]').click();

    // Verify sidebar is now expanded
    cy.get('[data-testid="sidebar-menu"]').should('have.class', 'collapsed');
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');

    // Verify toggle button reflects current state
    cy.get('[data-testid="sidebar-toggle"]').should('have.attr', 'aria-expanded', 'true');
  });

  it('should handle edge case when sidebar is already expanded', () => {
    // Verify sidebar is expanded by default
    cy.get('[data-testid="sidebar-menu"]').should('have.class', 'collapsed');

    // Click the toggle button to collapse
    cy.get('[data-testid="sidebar-toggle"]').click();

    // Verify sidebar is collapsed
    cy.get('[data-testid="sidebar-menu"]').should('not.have.class', 'collapsed');

    // Click the toggle button again to expand
    cy.get('[data-testid="sidebar-toggle"]').click();

    // Verify sidebar is expanded
    cy.get('[data-testid="sidebar-menu"]').should('have.class', 'collapsed');

    // Verify toggle button reflects current state
    cy.get('[data-testid="sidebar-toggle"]').should('have.attr', 'aria-expanded', 'true');
  });
});
